import re
import unicodedata
import hashlib


# Exact punctuation-, case-, accent-, and spacing-insensitive title key.
def exact_normalized_title(r):
    s = unicodedata.normalize("NFKD", r.get("title", ""))
    s = "".join(c for c in s if not unicodedata.combining(c)).casefold()
    s = " ".join(re.findall(r"[a-z0-9]+", s))
    if not s:
        return []
    return ["t:" + hashlib.sha1(s.encode()).hexdigest()[:12]]


# Independent title/brand token anchors, including embedded model-number components.
def token_anchors(r):
    def norm(s):
        s = unicodedata.normalize("NFKD", s)
        s = "".join(c for c in s if not unicodedata.combining(c)).casefold()
        return re.findall(r"[a-z0-9]+", s)

    title_tokens = norm(r.get("title", ""))
    brand_tokens = norm(r.get("brand", ""))
    alpha = [t for t in title_tokens if t.isalpha() and len(t) >= 3]
    chosen = set()

    if alpha:
        chosen.add("a:" + alpha[0])
        for t in sorted(alpha, key=lambda x: (len(x), title_tokens.index(x)))[:2]:
            chosen.add("a:" + t)
        for t in sorted(alpha, key=lambda x: (-len(x), title_tokens.index(x)))[:3]:
            chosen.add("a:" + t)

    for t in title_tokens + brand_tokens:
        if any(c.isdigit() for c in t) and len(t) >= 2:
            chosen.add("m:" + t)
        for part in re.findall(r"[a-z]+|[0-9]+", t):
            if part.isdigit() and len(part) >= 2:
                chosen.add("n:" + part)

    for t in brand_tokens[:2]:
        if len(t) >= 3:
            chosen.add("b:" + t)

    return sorted(
        "k:" + hashlib.sha1(x.encode()).hexdigest()[:11]
        for x in chosen
    )


# Character-prefix signatures tolerate suffix errors, spelling drift, and split model codes.
def character_fuzzy_signatures(r):
    s = unicodedata.normalize("NFKD", r.get("title", ""))
    s = "".join(c for c in s if not unicodedata.combining(c)).casefold()
    tokens = re.findall(r"[a-z0-9]+", s)
    sigs = set()

    alpha = [t for t in tokens if t.isalpha()]
    if alpha and len(alpha[0]) >= 4:
        sigs.add("f:" + alpha[0][:4])

    for t in alpha:
        if len(t) >= 6:
            skeleton = t[0] + re.sub(r"[aeiouy]", "", t[1:])
            if len(skeleton) >= 4:
                sigs.add("s:" + skeleton[:5])

    for i in range(len(tokens) - 1):
        joined = tokens[i] + tokens[i + 1]
        if (any(c.isalpha() for c in joined)
                and any(c.isdigit() for c in joined)
                and len(joined) >= 5):
            sigs.add("j:" + joined[:5])

    return sorted(
        "c:" + hashlib.sha1(x.encode()).hexdigest()[:11]
        for x in sigs
    )


# Standalone normalized price/description keys plus a bounded sparse-record fallback.
def tolerant_sparse_and_values(r):
    from decimal import Decimal, InvalidOperation

    def text_norm(s):
        s = unicodedata.normalize("NFKD", s)
        s = "".join(c for c in s if not unicodedata.combining(c)).casefold()
        return " ".join(re.findall(r"[a-z0-9]+", s))

    keys = []
    raw_price = r.get("price", "").strip()
    if raw_price:
        m = re.search(r"[-+]?(?:\d[\d\s.,]*)(?:[eE][-+]?\d+)?", raw_price)
        if m:
            p = re.sub(r"\s+", "", m.group())
            if "," in p and "." not in p:
                p = p.replace(",", ".")
            else:
                p = p.replace(",", "")
            try:
                p = format(Decimal(p).normalize(), "f")
                keys.append("p:" + hashlib.sha1(p.encode()).hexdigest()[:12])
            except InvalidOperation:
                pass

    desc = text_norm(r.get("description", ""))
    if len(desc) >= 40:
        keys.append("d:" + hashlib.sha1(desc.encode()).hexdigest()[:12])

    if not r.get("brand", "").strip() and not raw_price and not r.get("description", "").strip():
        title = text_norm(r.get("title", ""))
        if title:
            bucket = len(title) // 10
            keys.append("z:000:" + str(bucket))

    return sorted(set(keys))


SCHEMES = {
    "exact_normalized_title": exact_normalized_title,
    "token_anchors": token_anchors,
    "character_fuzzy_signatures": character_fuzzy_signatures,
    "tolerant_sparse_and_values": tolerant_sparse_and_values,
}
